import{_ as e,o as n,c as i,a2 as s}from"./chunks/framework.DtFGJNng.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1794463556000}'),t={name:"faq.md"};function r(d,a,o,u,p,k){return n(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>Apa bedanya deuz dengan OpenSpec?</strong> deuz memakai gagasan OpenSpec (spec permanen, work, delta, archive), lalu menambahkan peran dengan serah terima, konfirmasi per peran dengan hash, kontrak API bersama, dan gate persetujuan bisnis yang opsional. Ringkasannya ada di <a href="./alur-berpikir">Alur berpikir</a>, dan rinciannya di <a href="./decisions">Keputusan desain</a>.</p><p><strong>Apakah semua pekerjaan harus lewat deuz?</strong> Semua yang mengubah perilaku sistem, sebaiknya ya. Jalur engineer membuat bug fix dan perubahan teknis tetap ringan, cukup proposal sekitar sepuluh baris. Typo atau upgrade dependency kecil boleh disepakati tim untuk tidak memakai work.</p><p><strong>Sistem kami belum ada sama sekali. <code>deuz/specs/</code> diisi apa?</strong> Biarkan kosong. Spec lahir dari work pertama (delta <code>ADDED</code> dengan <code>## Purpose</code>) dan masuk ke home saat work itu di-archive. Pecah sistem baru menjadi beberapa work per capability, jangan satu work raksasa.</p><p><strong>Kenapa rencana tidak langsung ditulis ke <code>deuz/specs/</code>?</strong> Karena homes hanya berisi yang sudah dibangun. Kalau rencana ditulis ke sana lalu batal atau berubah, spec tidak lagi bisa dipercaya.</p><p><strong>Siapa yang boleh menjalankan <code>/deuz:ready</code>?</strong> Siapa saja, atas nama peran yang ia pegang. deuz mencatat peran, bukan orang. Di tim, setiap orang mengonfirmasi perannya sendiri. Dalam mode solo, satu orang bisa mengonfirmasi beberapa peran sekaligus.</p><p><strong>Stakeholder kami tidak memakai git. Bagaimana mereka menyetujui?</strong> Lewat rapat. Proposal ditampilkan langsung dari file <code>.md</code>. Analyst mencatat keputusan dan persetujuannya, lalu menjalankan <code>/deuz:ready … --as business</code>. Lihat <a href="./persetujuan-bisnis">Persetujuan bisnis</a>.</p><p><strong>Kami tidak butuh persetujuan bisnis formal.</strong> Jangan aktifkan role <code>business</code> di <code>config.yaml</code>. Semua aturan gate otomatis tidak berlaku.</p><p><strong>Bisakah dokumen diubah setelah <code>ready</code>?</strong> Bisa. Dokumen itu kembali <code>draft</code>, dan pemiliknya mengonfirmasi ulang. Dokumen sesudahnya diberi tanda <em>recheck</em>. Mencentang task tidak dihitung sebagai perubahan.</p><p><strong>Di mana keputusan teknis ditulis? Tidak ada <code>design.md</code>?</strong> Di bagian <em>Technical decisions</em> di awal setiap daftar task. Di tim yang punya designer, kata &quot;design&quot; berarti layar, jadi deuz tidak memakai nama itu untuk dokumen teknis.</p><p><strong>Kenapa kontrak API ditulis di Markdown, bukan langsung di OpenAPI?</strong> Kontrak adalah kesepakatan antara dua peran. Kalau langsung ditulis di OpenAPI, kesepakatan tercampur dengan tooling backend dan kode hasil generate. Backend menerjemahkannya ke OpenAPI sebagai task terakhir, bersama kode yang mengimplementasikannya.</p><p><strong>Bahasa dokumen bisa Bahasa Indonesia?</strong> Bisa. Set <code>language: id</code> di <code>config.yaml</code>. Hanya kata kunci format yang tetap bahasa Inggris. Daftarnya ada di <a href="./kustomisasi#bahasa">Kustomisasi</a>.</p><p><strong>Apakah ada tampilan navigasi antar dokumen seperti di Kiro?</strong><code>.deuz.yaml</code> berfungsi sebagai manifest navigasi (<code>format: 1</code>). Editor bisa membacanya untuk menampilkan langkah proposal → specs → … → tasks. Kontraknya ada di <a href="./manifest">Manifest work</a>.</p><p><strong>Bisa dipakai di beberapa repository sekaligus?</strong> Untuk sekarang, deuz mendukung satu repository (spec dan kode di tempat yang sama). Dukungan multi-repo belum ada.</p><p><strong>Bisa dipakai dengan agent selain Claude Code?</strong> CLI-nya bisa dipakai dari mana saja dan menghasilkan JSON yang sama. Skill-nya saat ini berupa plugin Claude Code.</p>',15)])])}const l=e(t,[["render",r]]);export{g as __pageData,l as default};
